<script setup lang="ts">
import {computed,onUnmounted,onMounted,ref,shallowRef,watch} from 'vue'
import {useI18n} from 'vue-i18n'
import {createCameraSession,type CameraState} from '../scanning/cameraSession'
import {normalizeGtin} from './gtin'
const props=withDefaults(defineProps<{disabled?:boolean;autoStart?:boolean;showManual?:boolean}>(),{autoStart:false,showManual:true}),emit=defineEmits<{code:[string]}>(),{locale}=useI18n(),en=computed(()=>locale.value.startsWith('en'))
const video=ref<HTMLVideoElement|null>(null),manual=ref(''),error=ref(''),reading=ref(false),state=shallowRef<CameraState>({phase:'idle',issue:null,facing:'environment',torchAvailable:false,torch:false})
let decoder:ReturnType<(typeof import('./decoder'))['createBarcodeDecoder']>|undefined,generation=0
const live=computed(()=>state.value.phase==='opening'||state.value.phase==='scanning')
function stop(){generation++;camera.stop()}
function found(v:string){const code=normalizeGtin(v);if(!code||props.disabled){error.value=en.value?'Enter a valid product barcode.':'请输入有效的商品条码';return}stop();error.value='';emit('code',v.trim())}
const camera=createCameraSession({getVideo:()=>video.value,secure:window.isSecureContext,mediaDevices:navigator.mediaDevices,requestFrame:cb=>requestAnimationFrame(cb),cancelFrame:id=>cancelAnimationFrame(id),decode:v=>decoder?.video(v)??null,accept:v=>!!normalizeGtin(v),onCode:found,onChange:v=>state.value=v})
async function prepare(){decoder??=(await import('./decoder')).createBarcodeDecoder()}
async function start(){if(props.disabled||reading.value)return;stop();const own=generation;try{await Promise.all([camera.start(),prepare()])}catch{if(own===generation){camera.stop();error.value=en.value?'Scanner unavailable. Enter the barcode manually.':'扫码暂不可用，请手动输入商品条码'}}}
async function image(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file||props.disabled||reading.value)return;stop();const own=generation;reading.value=true;error.value='';let url='';try{if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error();await prepare();url=URL.createObjectURL(file);const picture=new Image();picture.src=url;await picture.decode();if(own!==generation)return;const code=decoder!.image(picture);if(!code||!normalizeGtin(code))throw Error();found(code)}catch{if(own===generation)error.value=en.value?'Barcode not recognized. Try a clearer photo or enter it.':'未识别到条码，请拍清晰的条码照片或手动输入'}finally{if(url)URL.revokeObjectURL(url);input.value='';reading.value=false}}
function visibility(){if(document.visibilityState!=='visible')stop()}
watch(()=>props.disabled,v=>{if(v)stop()})
onMounted(()=>{document.addEventListener('visibilitychange',visibility);if(props.autoStart)void start()});onUnmounted(()=>{stop();camera.dispose();document.removeEventListener('visibilitychange',visibility)})
</script>
<template><div class="product-barcode-scanner"><div class="cards-actions"><button type="button" :disabled="disabled||reading" @click="live?stop():start()">{{live?(en?'Stop camera':'关闭摄像头'):(en?'Scan bottle barcode':'扫描瓶身商品条码')}}</button><details class="barcode-photo"><summary>{{en?'Read from photo (optional)':'拍照识别条码（可选）'}}</summary><label>{{en?'Choose a clear barcode photo':'选择清晰的条码照片'}}<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" :disabled="disabled||reading" @change="image"></label></details></div><video v-show="live" ref="video" playsinline muted aria-label="Product barcode camera"/><p v-if="live" role="status">{{en?'Keep the entire barcode inside the camera view.':'请将完整条码横向放入镜头中，保持清晰。'}}</p><p v-if="state.issue" role="alert">{{en?'Camera could not read the barcode. Retry or enter it below.':'摄像头暂未识别，请重试或在下方输入条码。'}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="reading" role="status">{{en?'Reading barcode…':'正在识别条码…'}}</p><div v-if="showManual" class="cards-actions"><label>{{en?'Product barcode':'商品条码号'}}<input v-model="manual" inputmode="numeric" maxlength="14" :disabled="disabled||reading" @keydown.enter.prevent="found(manual)"></label><button type="button" :disabled="disabled||reading||!manual.trim()" @click="found(manual)">{{en?'Use barcode':'使用条码'}}</button></div></div></template>
<style scoped>.product-barcode-scanner{padding:12px 0}.product-barcode-scanner video{width:100%;max-height:260px;border-radius:12px;background:#102630}.barcode-photo{font-size:14px;max-width:100%}.barcode-photo summary{cursor:pointer;padding:10px 0}.barcode-photo label{display:grid;gap:6px}.barcode-photo input{max-width:100%;width:230px}.product-barcode-scanner .cards-actions{flex-wrap:wrap}.product-barcode-scanner label{max-width:100%}</style>
